mapper.select:
/* selectReportStatsStudntResultList(통계보고서 - 교육생 결과) - Seoung Jae Lee */ SELECT A.BIZ_YR , A.INST_NM , A.INST_NO , A.PVSN_RESRCE_NM , A.RESRCE_NO , A.PVSN_BGNG_YMD , B.PROGRM_FNSH_EMPYMN_CUNT , B.PROGRM_FNSH_ERTDS_CUNT , B.PROGRM_FNSH_ETC_CUNT , B.MDSTRM_FAILR_ELPD_EMPYMN_CUNT , B.MDSTRM_FAILR_ELPD_ERTDS_CUNT , B.MDSTRM_FAILR_CUNT , B.EMPYMN_CUNT , B.ERTDS_CUNT FROM (SELECT C.BIZ_YR , A.INST_NM , A.INST_NO , D.PVSN_RESRCE_NM , D.RESRCE_NO , D.PVSN_BGNG_YMD , D.PVSN_END_YMD FROM SAA000 A INNER JOIN SDA100 D ON A.INST_NO = D.RSFR_INST_NO INNER JOIN SDA420 B ON D.SRVC_EXCN_BIZ_NO = B.SRVC_EXCN_BIZ_NO INNER JOIN SDA400 C ON B.SRVC_BIZ_NO = C.SRVC_BIZ_NO WHERE A.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND C.BIZ_YR = #{BIZ_YR} AND A.INST_NO LIKE #{INST_NO} || '%' AND D.RESRCE_NO LIKE #{RESRCE_NO} || '%' AND D.USE_YN = 'Y' AND D.APRV_STTS_SE_CD = '2' AND D.SRVC_RESRCE_LCLAS_SE_CD != '01' /*서비스자원대분류구분코드(상담)*/ GROUP BY C.BIZ_YR, A.INST_NO, A.INST_NM, D.RESRCE_NO, D.PVSN_RESRCE_NM, D.PVSN_BGNG_YMD, D.PVSN_END_YMD ) A
LEFT JOIN( SELECT D.BIZ_YR /*사업년도*/ , B.INST_NO /*기관번호*/ , B.INST_NM /*기관명*/ , A.RESRCE_NO /*자원번호*/ , A.PVSN_RESRCE_NM /*자원명*/ , COUNT(CASE WHEN G.TRMN_CS_SE_CD IN('042', '044', '047') THEN 1 END) AS PROGRM_FNSH_EMPYMN_CUNT /*수료후 취업한 인원수*/ , COUNT(CASE WHEN G.TRMN_CS_SE_CD IN('043', '045', '046') THEN 1 END) AS PROGRM_FNSH_ERTDS_CUNT /*수료후 진학한 인원수*/ , COUNT(CASE WHEN G.TRMN_CS_SE_CD IN('048') THEN 1 END) AS PROGRM_FNSH_ETC_CUNT /*수료후 기타*/ , COUNT(CASE WHEN G.TRMN_CS_SE_CD IN('054') THEN 1 END) AS MDSTRM_FAILR_ELPD_EMPYMN_CUNT /*중도탈락후 취업한 인원수*/ , COUNT(CASE WHEN G.TRMN_CS_SE_CD IN('055') THEN 1 END) AS MDSTRM_FAILR_ELPD_ERTDS_CUNT /*중도탈락후 진학한 인원수*/ , COUNT(CASE WHEN G.TRMN_CS_SE_CD IN('049', '050', '051', '052', '053', '056') THEN 1 END) AS MDSTRM_FAILR_CUNT /*중도탈락한 인원수*/ , COUNT(CASE WHEN G.TRMN_CS_SE_CD IN('042', '044', '047', '054') THEN 1 END) AS EMPYMN_CUNT /*취업인원수*/ , COUNT(CASE WHEN G.TRMN_CS_SE_CD IN('043', '045', '046', '055') THEN 1 END) AS ERTDS_CUNT /*진학인원수*/ FROM SDA100 A /*자원기본 테이블*/ INNER JOIN SAA000 B /*통합기관 테이블*/ ON A.RSFR_INST_NO = B.INST_NO /*기관번호*/ INNER JOIN SDA420 C /*서비스실행사업 테이블*/ ON A.SRVC_EXCN_BIZ_NO = C.SRVC_EXCN_BIZ_NO /*서비스실행사업번호*/ INNER JOIN SDA400 D /*서비스사업 테이블*/ ON C.SRVC_BIZ_NO = D.SRVC_BIZ_NO /*서비스사업번호*/ LEFT JOIN SEB510 F ON F.RESRCE_NO = A.RESRCE_NO AND F.DEL_YN = 'N' LEFT JOIN (SELECT BB.CASE_MNG_NO, BB.CASE_MNG_ODRNO, BB.TRMN_CS_SE_CD, AA.CASE_TRMN_YMD, BB.TRMN_SE_CD ,ROW_NUMBER() OVER(PARTITION BY BB.CASE_MNG_NO, BB.CASE_MNG_ODRNO ORDER BY BB.CASE_TRMN_NO DESC) AS RN FROM SEC100 AA /*사례종결 테이블*/ LEFT JOIN SEC100 BB ON BB.CASE_MNG_NO = AA.CASE_MNG_NO AND BB.CASE_MNG_NO = AA.CASE_MNG_NO AND BB.TRMN_SRNG_RESULT_SE_CD = '01' /*종결심사결과구분코드(신청)*/ WHERE AA.TRMN_SRNG_RESULT_SE_CD = '02' /*종결심사결과구분코드(심사(승인))*/ )G ON G.CASE_MNG_NO = F.CASE_MNG_NO AND G.CASE_MNG_ODRNO = F.CASE_MNG_ODRNO AND G.RN=1
WHERE 1=1 AND D.BIZ_YR = #{BIZ_YR} AND A.RESRCE_NO LIKE #{RESRCE_NO} || '%' AND B.INST_NO LIKE #{INST_NO} || '%' AND B.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD} AND A.USE_YN = 'Y' AND A.APRV_STTS_SE_CD = '2' AND A.SRVC_RESRCE_LCLAS_SE_CD != '01' /*서비스자원대분류구분코드(상담)*/ GROUP BY A.RESRCE_NO , A.PVSN_RESRCE_NM , B.INST_NO , B.INST_NM , D.BIZ_YR , A.UTZTN_PSNCPA_NOPE , A.PTCPTN_NOPE , A.PVSN_BGNG_YMD , A.PVSN_END_YMD) B ON A.INST_NO = B.INST_NO AND A.RESRCE_NO = B.RESRCE_NO ORDER BY A.INST_NO, A.PVSN_BGNG_YMD
